import sys

input = sys.stdin.readline

def in2i():
    '''
    input to int
    '''
    return int(input())

def in2il():
    '''
    intput to int list
    '''
    return (list(map(int, input().split())))

def s2cs():
    '''
    string to chars
    '''
    s = input()
    return (list(s[:len(s)]))

